import paypalrestsdk
from paypalrestsdk import Payment

class PayPalAgent:
    def __init__(self, client_id, client_secret):
        paypalrestsdk.configure({
          "mode": "live",  # Use "sandbox" for testing
          "client_id": client_id,
          "client_secret": client_secret
        })

    def execute_transfer(self, amount, currency, sender_email, receiver_email):
        payment = Payment({
            "intent": "sale",
            "payer": {"payment_method": "paypal"},
            "transactions": [{
                "amount": {"total": str(amount), "currency": currency},
                "payee": {"email": receiver_email}
            }],
            "redirect_urls": {"return_url": "https://your-domain.com/return"}
        })
        if payment.create():
            return {"status": "success", "payment_id": payment.id}
        else:
            return {"status": "error", "details": payment.error}
